    inline int Find(const char* name)
    {
        static const char* const names[IconCount] = { "pistol", "shotgun", "carbine", "flaregun", "knife", "shield", "water", "battery", "flare", "medkit", "bandage", "doc", "sample", "scrap", "wire", "fuel", "helmet", "vest", "mask", "nv", "radio", "tracker", "light", "shells", "rounds", "lock", "foundation" };
        for (int i = 0; i < IconCount; ++i)
        {
            const char* a = names[i];
            const char* b = name;
            while (*a && *a == *b) { ++a; ++b; }
            if (*a == 0 && *b == 0) { return i; }
        }
        return -1;
    }
